import sys
from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def create_tree(parent, n):
    nodes = [Node(i) for i in range(n)]
    root = None
    children_count = {}

    for i, p in enumerate(parent):
        if p == -1:
            root = nodes[i]
        else:
            if p not in children_count:
                children_count[p] = []
            children_count[p].append(nodes[i])

    for p, kids in children_count.items():
        if len(kids) >= 1:
            nodes[p].left = kids[0]
        if len(kids) >= 2:
            nodes[p].right = kids[1]

    return root

def level_order(root):
    if not root:
        return []
    result = []
    q = deque([root])
    while q:
        node = q.popleft()
        result.append(node.val)
        if node.left:
            q.append(node.left)
        if node.right:
            q.append(node.right)
    return result

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    if idx < len(input_data):
        n = int(input_data[idx])
        idx += 1
    else:
        return
    parent = []
    for _ in range(n):
        if idx < len(input_data):
            parent.append(int(input_data[idx]))
            idx += 1

    root = create_tree(parent, n)
    traversal = level_order(root)
    print(' '.join(map(str, traversal)))

if __name__ == "__main__":
    main()
